SELECT u.user_id, u.user_no, u.user_name, u.phone, u.dept_name, u.register_time, u.account_status, CASE u.account_status WHEN 0 THEN 'disabled' WHEN 1 THEN 'normal' END AS account_status_text, u.role_id, r.role_name FROM sys_user u JOIN sys_role r ON u.role_id = r.role_id
AND ( u.user_no LIKE CONCAT('%', #{keyword}, '%') OR u.user_name LIKE CONCAT('%', #{keyword}, '%') OR u.phone LIKE CONCAT('%', #{keyword}, '%') OR u.dept_name LIKE CONCAT('%', #{keyword}, '%') )
AND u.role_id = #{roleId}
AND u.account_status = #{status}
ORDER BY u.user_id DESC

